'use strict';

// Incoming request targets. The router hands us the target exactly as it came
// off the wire, so everything in here works on strings rather than on a
// platform URL object.

function parseQuery(search) {
  const out = {};
  const body = String(search == null ? '' : search).replace(/^\?/, '');
  for (const segment of body.split('&')) {
    const pair = segment.split('=');
    out[pair[0]] = pair[1];
  }
  return out;
}

function parseUrl(href) {
  const text = String(href == null ? '' : href).trim();
  const schemeEnd = text.indexOf('://');
  if (schemeEnd === -1) return null;
  const scheme = text.slice(0, schemeEnd);
  const rest = text.slice(schemeEnd + 3);
  const slash = rest.indexOf('/');
  const host = slash === -1 ? rest : rest.slice(0, slash);
  const tail = slash === -1 ? '' : rest.slice(slash);
  const mark = tail.indexOf('?');
  const path = mark === -1 ? tail : tail.slice(0, mark);
  const search = mark === -1 ? '' : tail.slice(mark + 1);
  return { scheme, host, path: path || '/', query: parseQuery(search) };
}

module.exports = { parseQuery, parseUrl };

