'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { parseQuery, parseUrl, resolve, toQuery } = require('./src/url.js');
const { redirectTarget } = require('./src/link.js');

test('s1 percent escapes are decoded on both sides of a pair', () => {
  assert.deepStrictEqual(parseQuery('q=red%20shoes'), { q: 'red shoes' });
  assert.deepStrictEqual(parseQuery('q=caf%C3%A9'), { q: 'caf\u00e9' });
  assert.deepStrictEqual(parseQuery('a%5Bb%5D=1'), { 'a[b]': '1' }, 'the key is decoded too');

  // The separators are found before anything is decoded, so an escaped one
  // stays inside the value it belongs to.
  assert.deepStrictEqual(parseQuery('q=a%26b'), { q: 'a&b' }, 'an escaped ampersand does not split a pair');
  assert.deepStrictEqual(parseQuery('q=x%3Dy'), { q: 'x=y' }, 'an escaped equals sign does not split a pair');

  assert.deepStrictEqual(parseQuery('plain=text'), { plain: 'text' }, 'text with no escapes is untouched');
  assert.deepStrictEqual(parseQuery('a=1&b=2'), { a: '1', b: '2' }, 'ordinary pairs still come back');
});

test('s2 a literal plus is a space and an escaped one is a plus sign', () => {
  assert.deepStrictEqual(parseQuery('q=hello+world'), { q: 'hello world' });
  assert.deepStrictEqual(parseQuery('first+name=ada'), { 'first name': 'ada' }, 'the key gets the same treatment');
  assert.deepStrictEqual(parseQuery('q=a%2Bb'), { q: 'a+b' }, '%2B is a genuine plus sign');
  assert.deepStrictEqual(parseQuery('q=1+%2B+2'), { q: '1 + 2' }, 'the substitution happens before the escapes are read');
  assert.deepStrictEqual(parseQuery('phone=%2B44+7700'), { phone: '+44 7700' });
  assert.deepStrictEqual(parseQuery('q=red%20shoes'), { q: 'red shoes' }, 'escaped spaces still decode');
});

test('s3 a repeated key comes back as an array in the order it appeared', () => {
  assert.deepStrictEqual(parseQuery('tag=red&tag=blue&tag=green'), { tag: ['red', 'blue', 'green'] });
  assert.deepStrictEqual(parseQuery('x=1&x=2&x=3&x=4'), { x: ['1', '2', '3', '4'] });
  assert.deepStrictEqual(parseQuery('a=1&b=2&a=3'), { a: ['1', '3'], b: '2' }, 'only the repeated key becomes an array');
  assert.deepStrictEqual(parseQuery('tag=a%20b&tag=c+d'), { tag: ['a b', 'c d'] }, 'the values in an array are decoded');

  const single = parseQuery('tag=red');
  assert.strictEqual(typeof single.tag, 'string', 'a key that appears once stays a plain string');
  assert.strictEqual(single.tag, 'red');
});

test('s4 empty values, bare keys and empty segments', () => {
  assert.deepStrictEqual(parseQuery('a=&b=2'), { a: '', b: '2' }, 'nothing after the equals is an empty string');
  assert.deepStrictEqual(parseQuery('flag&b=2'), { flag: '', b: '2' }, 'a bare key is present and empty');
  assert.deepStrictEqual(parseQuery('a=1&&b=2&'), { a: '1', b: '2' }, 'an empty segment is not a pair');
  assert.deepStrictEqual(parseQuery('&'), {}, 'separators on their own produce nothing');
  assert.deepStrictEqual(parseQuery(''), {});
  assert.deepStrictEqual(parseQuery(null), {});
  assert.deepStrictEqual(parseQuery('t=YWJjZA=='), { t: 'YWJjZA==' }, 'only the first equals separates the pair');
  assert.deepStrictEqual(parseQuery('?a=1&b=2'), { a: '1', b: '2' }, 'the leading question mark is still stripped');
  assert.deepStrictEqual(parseQuery('tag=&tag=red'), { tag: ['', 'red'] }, 'an empty value can be one of a repeated key');
});

test('s5 a malformed escape is left as written and never throws', () => {
  assert.doesNotThrow(() => parseQuery('q=%zz'));
  assert.doesNotThrow(() => parseQuery('q=100%'));
  assert.doesNotThrow(() => parseQuery('q=%'));

  assert.deepStrictEqual(parseQuery('q=%zz'), { q: '%zz' }, 'a per cent sign without two hex digits is literal');
  assert.deepStrictEqual(parseQuery('q=50%'), { q: '50%' });
  assert.deepStrictEqual(parseQuery('q=%2'), { q: '%2' });
  assert.deepStrictEqual(parseQuery('q=100%25'), { q: '100%' }, 'a well formed escape still decodes');
  assert.deepStrictEqual(parseQuery('%zz=1'), { '%zz': '1' }, 'the same on the key side');

  // A run of escapes that is not valid text stays exactly as it was written,
  // rather than being dropped or swapped for a replacement character.
  assert.deepStrictEqual(parseQuery('q=%C3'), { q: '%C3' });
  assert.deepStrictEqual(parseQuery('q=%E2%82%ACx%zz%41'), { q: '\u20acx%zzA' }, 'the good escapes around it still decode');
  assert.deepStrictEqual(parseQuery('q=caf%C3%A9'), { q: 'caf\u00e9' }, 'a multi byte character still decodes');
});

test('s6 the fragment is cut off before the query is read', () => {
  const docs = parseUrl('https://example.com/docs?page=2#install');
  assert.deepStrictEqual(docs.query, { page: '2' }, 'the fragment is not part of the query');
  assert.strictEqual(docs.fragment, 'install');
  assert.strictEqual(docs.path, '/docs');

  const early = parseUrl('https://example.com/docs#a?b=c');
  assert.deepStrictEqual(early.query, {}, 'a question mark after the hash is part of the fragment');
  assert.strictEqual(early.fragment, 'a?b=c');

  assert.strictEqual(parseUrl('https://example.com/docs').fragment, null, 'no hash at all is null');
  assert.strictEqual(parseUrl('https://example.com/docs#').fragment, '', 'a hash with nothing after it is an empty string');

  assert.strictEqual(parseUrl('https://example.com/d#a%20b').fragment, 'a b', 'a fragment is decoded');
  assert.strictEqual(parseUrl('https://example.com/d#a+b').fragment, 'a+b', 'a plus in a fragment is a plus sign');

  assert.strictEqual(parseUrl('https://example.com/a+b/c%20d?q=x').path, '/a+b/c%20d', 'the path comes back as written');
  assert.strictEqual(parseUrl('https://example.com').path, '/', 'an empty path is still a slash');
});

test('s7 the scheme and the host are lower cased and nothing else is', () => {
  const mixed = parseUrl('HTTPS://Example.COM/Path?A=B#Frag');
  assert.strictEqual(mixed.scheme, 'https');
  assert.strictEqual(mixed.host, 'example.com');
  assert.strictEqual(mixed.path, '/Path', 'the path keeps its case');
  assert.deepStrictEqual(mixed.query, { A: 'B' }, 'the query keeps its case');
  assert.strictEqual(mixed.fragment, 'Frag', 'the fragment keeps its case');

  assert.strictEqual(parseUrl('HtTp://EXAMPLE.com/x').scheme, 'http');
  assert.strictEqual(parseUrl('HtTp://EXAMPLE.com/x').host, 'example.com');

  const idn = parseUrl('https://M\u00dcNCHEN.example/Stra\u00dfe?q=Wei\u00df#Gr\u00fc\u00dfe');
  assert.strictEqual(idn.host, 'm\u00fcnchen.example', 'a host that is not ASCII is lower cased too');
  assert.strictEqual(idn.path, '/Stra\u00dfe');
  assert.deepStrictEqual(idn.query, { q: 'Wei\u00df' });
  assert.strictEqual(idn.fragment, 'Gr\u00fc\u00dfe');

  assert.strictEqual(parseUrl('http://Example.com./x').host, 'example.com', 'a trailing dot is the same name');
  assert.strictEqual(parseUrl('http://example.com/x').host, 'example.com', 'a host that needs nothing done to it is untouched');
});

test('s8 the port is split off the host and a default port is dropped', () => {
  const custom = parseUrl('http://example.com:8080/x');
  assert.strictEqual(custom.host, 'example.com', 'the host is the name on its own');
  assert.strictEqual(custom.port, 8080);
  assert.strictEqual(typeof custom.port, 'number', 'the port is a number, not a string');

  assert.strictEqual(parseUrl('http://example.com:80/x').port, null, 'http on 80 is the default');
  assert.strictEqual(parseUrl('http://example.com:80/x').host, 'example.com');
  assert.strictEqual(parseUrl('https://example.com:443/x').port, null);
  assert.strictEqual(parseUrl('ws://example.com:80/x').port, null);
  assert.strictEqual(parseUrl('wss://example.com:443/x').port, null);
  assert.strictEqual(parseUrl('ftp://example.com:21/x').port, null);
  assert.strictEqual(parseUrl('https://example.com:8443/x').port, 8443, 'a port that is not the default is kept');
  assert.strictEqual(parseUrl('http://example.com:443/x').port, 443, 'the default belongs to the scheme, not to the number');
  assert.strictEqual(parseUrl('redis://example.com:6379/x').port, 6379, 'a scheme with no default keeps its port');
  assert.strictEqual(parseUrl('http://example.com/x').port, null, 'no port at all is null');
  assert.strictEqual(parseUrl('http://example.com:/x').port, null, 'a colon with nothing after it is no port');
  assert.strictEqual(parseUrl('http://example.com:/x').host, 'example.com');
  assert.strictEqual(parseUrl('http://example.com:65535/x').port, 65535);

  const both = parseUrl('HTTP://Example.com.:8080/x');
  assert.strictEqual(both.host, 'example.com', 'the trailing dot and the port come off the same host');
  assert.strictEqual(both.port, 8080);

  assert.strictEqual(parseUrl('http://example.com:80x/y'), null, 'a port that is not all digits is unreadable');
  assert.strictEqual(parseUrl('http://example.com:abc/y'), null);
  assert.strictEqual(parseUrl('http://example.com:0/y'), null, 'zero is outside the range');
  assert.strictEqual(parseUrl('http://example.com:65536/y'), null, 'one past the top of the range');
  assert.strictEqual(parseUrl('/docs/index.html'), null, 'a target with no scheme is still unreadable');
});

test('s9 the tracking link gives back its target, or refuses with a code', () => {
  const full = redirectTarget('/go?next=%2Fdashboard%3Ftab%3Dbilling%26sort%3Dasc');
  assert.strictEqual(full.ok, true);
  assert.strictEqual(full.to, '/dashboard?tab=billing&sort=asc', 'the whole target survives, ampersand and all');

  assert.strictEqual(redirectTarget('/go?next=%2Fa%23top').to, '/a#top', 'an escaped hash inside the target survives');
  assert.strictEqual(redirectTarget('/go?next=%2Fa#anchor').to, '/a', 'a fragment on the link itself is not part of the query');
  assert.strictEqual(redirectTarget('/go?next=%2Freports&campaign=spring').to, '/reports', 'the other parameters are left alone');

  assert.doesNotThrow(() => redirectTarget('/go?next=%2Fa&raw=%zz'), 'a malformed escape elsewhere in the link cannot throw');
  assert.strictEqual(redirectTarget('/go?next=%2Fa&raw=%zz').to, '/a');

  const twice = redirectTarget('/go?next=%2Fa&next=%2Fb');
  assert.strictEqual(twice.ok, false, 'two targets is not a matter of taste');
  assert.strictEqual(twice.code, 'ambiguous');

  const offsite = redirectTarget('/go?next=https%3A%2F%2Fevil.example%2F');
  assert.strictEqual(offsite.ok, false);
  assert.strictEqual(offsite.code, 'off_site');
  assert.strictEqual(redirectTarget('/go?next=%2F%2Fevil.example%2Fx').code, 'off_site', 'a protocol relative target is another site');
  assert.strictEqual(redirectTarget('/go?next=dashboard').code, 'off_site', 'a target that is not a path is refused');

  assert.strictEqual(redirectTarget('/go?campaign=spring').code, 'no_target');
  assert.strictEqual(redirectTarget('/go?next=').code, 'no_target', 'an empty target is no target');
  assert.strictEqual(redirectTarget('/dashboard').code, 'no_target');
  assert.strictEqual(redirectTarget(null).code, 'no_target');
});

test('s10 resolve handles the reference kinds that are not a relative path', () => {
  const base = 'http://Example.com/a/b/c?x=1#frag';

  assert.strictEqual(resolve(base, 'https://other.example/z'), 'https://other.example/z', 'a full reference wins outright');
  assert.strictEqual(resolve(base, 'HTTPS://Other.Example/Z?q=1#f'), 'https://other.example/Z?q=1#f', 'and it is tidied on the way out');
  assert.strictEqual(resolve(base, 'https://other.example:443/z'), 'https://other.example/z', 'including its default port');
  assert.strictEqual(resolve(base, 'HTTPS://M\u00dcNCHEN.Example:443/Z'), 'https://m\u00fcnchen.example/Z', 'a host that is not ASCII is folded the way parseUrl folds it');

  assert.strictEqual(resolve('https://example.com/a/b', '//cdn.Example.com/lib.js'), 'https://cdn.example.com/lib.js', 'a protocol relative reference takes the scheme from the base');

  assert.strictEqual(resolve('https://example.com:8443/a/b?x=1#f', '/root/x?y=2#g'), 'https://example.com:8443/root/x?y=2#g');
  assert.strictEqual(resolve('https://example.com:443/a/b', '/x'), 'https://example.com/x', 'the base default port is dropped');
  assert.strictEqual(resolve('http://EXAMPLE.com:80/a/b', '/x'), 'http://example.com/x');
  assert.strictEqual(resolve('http://Example.com./a/b', '/x'), 'http://example.com/x', 'and the base trailing root-label dot comes off');
  assert.strictEqual(resolve('http://example.com/a/b', '/v2/{id}/edit?q=1#top'), 'http://example.com/v2/{id}/edit?q=1#top', 'the path, query and fragment are copied across rather than re-escaped');

  assert.strictEqual(resolve('http://example.com/a/b?x=1#f', '?y=2'), 'http://example.com/a/b?y=2', 'a query only reference keeps the path and drops the fragment');
  assert.strictEqual(resolve('http://example.com/a/b?x=1#f', '#g'), 'http://example.com/a/b?x=1#g', 'a fragment only reference keeps the query');
  assert.strictEqual(resolve('http://example.com/a/b?x=1#f', ''), 'http://example.com/a/b?x=1', 'an empty reference drops the fragment');
  assert.strictEqual(resolve('http://example.com/a/b?x=1#f'), 'http://example.com/a/b?x=1', 'no reference at all is the same as an empty one');
  assert.strictEqual(resolve('http://example.com', '?y=2'), 'http://example.com/?y=2', 'a base with no path is read as a slash');

  assert.strictEqual(resolve('/not/absolute', '/x'), null, 'a base the parser cannot read has no answer');
  assert.strictEqual(resolve('http://example.com:0/a', '/x'), null, 'and that includes a base with an impossible port');
});

test('s11 a relative reference is merged against the base directory and tidied', () => {
  const base = 'http://example.com/a/b/c';

  assert.strictEqual(resolve(base, 'd'), 'http://example.com/a/b/d', 'everything after the last slash is dropped');
  assert.strictEqual(resolve('http://example.com/a/b/', 'd'), 'http://example.com/a/b/d');
  assert.strictEqual(resolve('http://example.com/a/b/c?x=1#f', 'd'), 'http://example.com/a/b/d', 'the query and fragment of the base do not carry over');
  assert.strictEqual(resolve('http://example.com', 'd'), 'http://example.com/d', 'a base with no path is read as a slash');

  assert.strictEqual(resolve(base, './d'), 'http://example.com/a/b/d');
  assert.strictEqual(resolve(base, '../d'), 'http://example.com/a/d');
  assert.strictEqual(resolve(base, '../../d'), 'http://example.com/d');
  assert.strictEqual(resolve(base, '../../../../d'), 'http://example.com/d', 'a climb above the root is dropped rather than escaping it');
  assert.strictEqual(resolve(base, 'd/e/../f'), 'http://example.com/a/b/d/f');

  assert.strictEqual(resolve(base, '.'), 'http://example.com/a/b/', 'a reference that is exactly a dot is a directory');
  assert.strictEqual(resolve(base, '..'), 'http://example.com/a/');

  assert.strictEqual(resolve(base, 'd?q=1#z'), 'http://example.com/a/b/d?q=1#z', 'the reference brings its own query and fragment');

  assert.strictEqual(resolve('http://example.com/a/b', '/x/../y'), 'http://example.com/y', 'the same tidy up applies to a rooted reference');
  assert.strictEqual(resolve('http://example.com/a/b', '/x/./y/'), 'http://example.com/x/y/');

  assert.strictEqual(resolve('http://example.com/a/b', 'v2/{id}/edit'), 'http://example.com/a/v2/{id}/edit', 'a merged path is copied across rather than re-escaped');
  assert.strictEqual(resolve('https://M\u00dcNCHEN.example/a/b/c', '../d'), 'https://m\u00fcnchen.example/a/d', 'the front of the result is tidied here too');
  assert.strictEqual(resolve('http://example.com./a/b/c', 'd'), 'http://example.com/a/b/d', 'trailing root-label dot and all');
});

test('s12 toQuery writes a stable query string that reads back', () => {
  assert.strictEqual(toQuery({}), '', 'an empty object is an empty string');
  assert.strictEqual(toQuery({ b: '2', a: '1' }), 'a=1&b=2', 'the keys are sorted');
  assert.strictEqual(toQuery({ q: 'a b&c' }), 'q=a+b%26c', 'a space is a plus and a separator is escaped');
  assert.strictEqual(toQuery({ 'a b': 'c d' }), 'a+b=c+d', 'the key gets the same treatment');
  assert.strictEqual(toQuery({ q: '+' }), 'q=%2B', 'a genuine plus sign is escaped');
  assert.strictEqual(toQuery({ q: '=' }), 'q=%3D');
  assert.strictEqual(toQuery({ q: 'caf\u00e9' }), 'q=caf%C3%A9', 'upper case hex digits');
  assert.strictEqual(toQuery({ q: 'a-b.c_d~e' }), 'q=a-b.c_d~e', 'the unreserved characters are left alone');
  assert.strictEqual(toQuery({ q: "a!b'c(d)e*f" }), 'q=a%21b%27c%28d%29e%2Af', 'everything else is escaped');

  assert.strictEqual(toQuery({ a: '1', tag: ['red', 'blue'] }), 'a=1&tag=red&tag=blue', 'an array keeps its own order under one key');
  assert.strictEqual(toQuery({ a: '' }), 'a=', 'an empty value keeps its equals sign');
  assert.strictEqual(toQuery({ a: null, b: undefined }), 'a&b', 'a missing value is a bare key');
  assert.strictEqual(toQuery({ a: [], b: '1' }), 'b=1', 'an empty array writes nothing');
  assert.strictEqual(toQuery({ n: 5, t: true }), 'n=5&t=true', 'a number or a boolean is written the way it prints');
  assert.strictEqual(toQuery({ z: '2', '\u00e9': '1' }), 'z=2&%C3%A9=1', 'the sort happens on the key before it is escaped');

  const original = { q: 'a b&c=d', tag: ['x', 'y'], 'k\u00e9y': '100%', empty: '' };
  assert.deepStrictEqual(parseQuery(toQuery(original)), original, 'what it writes is what the parser reads back');
});

