'use strict';

// Incoming request targets. The router hands us the target exactly as it came
// off the wire, so everything in here works on strings rather than on a
// platform URL object.

const DEFAULT_PORTS = { http: 80, https: 443, ws: 80, wss: 443, ftp: 21 };

// Percent decoding that cannot throw. A run of well formed escapes is decoded
// in one go, because a single character can be spread across several of them;
// a run that does not decode to valid text, and a '%' that is not followed by
// two hex digits, are left exactly as they were written.
function percentDecode(text) {
  return String(text).replace(/(?:%[0-9A-Fa-f]{2})+/g, (run) => {
    try {
      return decodeURIComponent(run);
    } catch (err) {
      return run;
    }
  });
}

// A '+' is a space in a query string and nowhere else, and the substitution
// happens before the escapes are read so that %2B survives as a plus sign.
function decodeQueryPart(text) {
  return percentDecode(String(text).replace(/\+/g, ' '));
}

function parseQuery(search) {
  const out = {};
  const body = String(search == null ? '' : search).replace(/^\?/, '');
  for (const segment of body.split('&')) {
    if (segment === '') continue;
    const eq = segment.indexOf('=');
    const key = decodeQueryPart(eq === -1 ? segment : segment.slice(0, eq));
    const value = decodeQueryPart(eq === -1 ? '' : segment.slice(eq + 1));
    if (!Object.prototype.hasOwnProperty.call(out, key)) {
      out[key] = value;
    } else if (Array.isArray(out[key])) {
      out[key].push(value);
    } else {
      out[key] = [out[key], value];
    }
  }
  return out;
}

// The raw pieces of a target, nothing decoded and nothing tidied. The fragment
// comes off first, so a '#' before any '?' leaves no query behind it.
function splitParts(href) {
  const text = String(href == null ? '' : href).trim();
  const schemeEnd = text.indexOf('://');
  if (schemeEnd === -1) return null;
  const scheme = text.slice(0, schemeEnd).toLowerCase();
  let rest = text.slice(schemeEnd + 3);
  let fragment = null;
  const hash = rest.indexOf('#');
  if (hash !== -1) {
    fragment = rest.slice(hash + 1);
    rest = rest.slice(0, hash);
  }
  let query = null;
  const mark = rest.indexOf('?');
  if (mark !== -1) {
    query = rest.slice(mark + 1);
    rest = rest.slice(0, mark);
  }
  const slash = rest.indexOf('/');
  return {
    scheme,
    authority: slash === -1 ? rest : rest.slice(0, slash),
    path: slash === -1 ? '' : rest.slice(slash),
    query,
    fragment,
  };
}

// Host names are case insensitive and a trailing dot is the root label, so both
// spellings have to land in the same cache bucket. A port that is the scheme's
// default says nothing, so it is dropped.
function splitAuthority(authority, scheme) {
  const raw = String(authority);
  let host = raw;
  let port = null;
  const colon = raw.lastIndexOf(':');
  if (colon !== -1) {
    host = raw.slice(0, colon);
    const portText = raw.slice(colon + 1);
    if (portText !== '') {
      if (!/^[0-9]+$/.test(portText)) return null;
      const value = Number(portText);
      if (value < 1 || value > 65535) return null;
      port = value;
    }
  }
  host = host.toLowerCase();
  if (host.length > 1 && host.endsWith('.')) host = host.slice(0, -1);
  if (port !== null && DEFAULT_PORTS[scheme] === port) port = null;
  return { host, port };
}

function parseUrl(href) {
  const parts = splitParts(href);
  if (parts === null) return null;
  const authority = splitAuthority(parts.authority, parts.scheme);
  if (authority === null) return null;
  return {
    scheme: parts.scheme,
    host: authority.host,
    port: authority.port,
    path: parts.path || '/',
    query: parseQuery(parts.query === null ? '' : parts.query),
    fragment: parts.fragment === null ? null : percentDecode(parts.fragment),
  };
}

// RFC 3986 remove_dot_segments, segment by segment. A '..' that would climb
// above the root is dropped, and a trailing '.' or '..' leaves a directory.
function removeDotSegments(path) {
  const segments = String(path).split('/');
  const out = [];
  for (let i = 0; i < segments.length; i += 1) {
    const segment = segments[i];
    const last = i === segments.length - 1;
    if (segment === '.') {
      if (last) out.push('');
      continue;
    }
    if (segment === '..') {
      if (out.length > 1) out.pop();
      if (last) out.push('');
      continue;
    }
    out.push(segment);
  }
  return out.join('/');
}

function format(scheme, authority, path, query, fragment) {
  let out = scheme + '://' + authority.host;
  if (authority.port !== null) out += ':' + authority.port;
  out += path || '/';
  if (query !== null && query !== undefined) out += '?' + query;
  if (fragment !== null && fragment !== undefined) out += '#' + fragment;
  return out;
}

function formatAbsolute(text) {
  const parts = splitParts(text);
  if (parts === null) return null;
  const authority = splitAuthority(parts.authority, parts.scheme);
  if (authority === null) return null;
  return format(
    parts.scheme,
    authority,
    removeDotSegments(parts.path || '/'),
    parts.query,
    parts.fragment
  );
}

function resolve(base, ref) {
  const baseParts = splitParts(base);
  if (baseParts === null) return null;
  const baseAuthority = splitAuthority(baseParts.authority, baseParts.scheme);
  if (baseAuthority === null) return null;
  const basePath = baseParts.path || '/';

  const text = String(ref == null ? '' : ref).trim();

  // A reference with a scheme of its own wins outright, and one that starts
  // '//' borrows only the scheme from the base.
  if (/^[A-Za-z][A-Za-z0-9+.-]*:\/\//.test(text)) return formatAbsolute(text);
  if (text.slice(0, 2) === '//') return formatAbsolute(baseParts.scheme + ':' + text);

  let rest = text;
  let fragment = null;
  const hash = rest.indexOf('#');
  if (hash !== -1) {
    fragment = rest.slice(hash + 1);
    rest = rest.slice(0, hash);
  }
  let query = null;
  const mark = rest.indexOf('?');
  if (mark !== -1) {
    query = rest.slice(mark + 1);
    rest = rest.slice(0, mark);
  }

  let path;
  if (rest === '') {
    // Nothing but a query or a fragment: the base keeps its path, and its own
    // query only when the reference brought none.
    path = basePath;
    if (query === null) query = baseParts.query;
  } else if (rest.charAt(0) === '/') {
    path = removeDotSegments(rest);
  } else {
    path = removeDotSegments(basePath.slice(0, basePath.lastIndexOf('/') + 1) + rest);
  }
  return format(baseParts.scheme, baseAuthority, path, query, fragment);
}

// The mirror of the reading side. Everything outside the unreserved set is
// escaped, including the '+', '&' and '=' that would otherwise be read back as
// structure, and the key order is fixed so the string can be a cache key.
function encodeQueryPart(text) {
  return encodeURIComponent(String(text))
    .replace(/[!'()*]/g, (ch) => '%' + ch.charCodeAt(0).toString(16).toUpperCase())
    .replace(/%20/g, '+');
}

function toQuery(params) {
  if (params === null || typeof params !== 'object') return '';
  const out = [];
  for (const key of Object.keys(params).sort()) {
    const encodedKey = encodeQueryPart(key);
    const value = params[key];
    const values = Array.isArray(value) ? value : [value];
    for (const item of values) {
      if (item === null || item === undefined) out.push(encodedKey);
      else out.push(encodedKey + '=' + encodeQueryPart(item));
    }
  }
  return out.join('&');
}

module.exports = { parseQuery, parseUrl, resolve, toQuery };

