'use strict';

const { parseQuery } = require('./url.js');

// Tracking links arrive as /go?next=<the target>&campaign=<id>. The click
// handler needs the target back out of them before it can send the browser on.
//
// The query goes to the parser exactly as it was written: it decodes each value
// on its own, which is the only way a separator inside the target survives.
function redirectTarget(href) {
  const text = String(href == null ? '' : href);
  const hash = text.indexOf('#');
  const link = hash === -1 ? text : text.slice(0, hash);
  const mark = link.indexOf('?');
  if (mark === -1) return { ok: false, code: 'no_target' };

  const next = parseQuery(link.slice(mark + 1)).next;
  if (Array.isArray(next)) return { ok: false, code: 'ambiguous' };
  if (typeof next !== 'string' || next === '') return { ok: false, code: 'no_target' };
  // A path on this site starts with one slash. Two of them is another host
  // wearing a path's clothes.
  if (next.charAt(0) !== '/' || next.charAt(1) === '/') return { ok: false, code: 'off_site' };
  return { ok: true, to: next };
}

module.exports = { redirectTarget };
